import type * as THREE from 'three';
import type { LocalPoint, LocalPoint3 } from '../contracts';
import type { SceneOrigin, UnifiedPoi } from './coordBridge';

export type { SceneOrigin, UnifiedPoi } from './coordBridge';

/** Clipmap ring tiers generated by the Marswalk site pipeline. */
export type TerrainRingName = 'inner' | 'mid' | 'outer';

/** Geographic/DEM ring metadata stored in `public/sites/jezero-delta/site.json`. */
export interface TerrainRingSpec {
  readonly name: TerrainRingName;
  /** Half-extent of the square ring around Jezero VR origin, in meters. */
  readonly half: number;
  /** Native horizontal sampling interval, in meters per sample. */
  readonly res: number;
  /** Grid side sample count (`n x n` samples). */
  readonly n: number;
  readonly tile: number;
  readonly lods: readonly number[];
  readonly lodDist: readonly number[];
  /** Minimum height in areoid meters decoded by uint16 height bins. */
  readonly hmin: number;
  /** Scale in meters per uint16 step (`elev_m = hmin + u16 * hscale`). */
  readonly hscale: number;
  readonly orthoTiles: number;
  readonly slopeMax?: number;
}

/**
 * Raw POI entry parsed from `site.json`.
 * Note: `title`, `text`, and `label` in `site.json` contain Italian draft copy and
 * MUST NEVER be rendered in UI; display authoritative English `UnifiedPoi` metadata instead.
 */
export interface SitePoiRaw {
  readonly id: string;
  readonly label?: string;
  readonly title?: string;
  readonly text?: string;
  readonly vr?: readonly [number, number];
  readonly x?: number;
  readonly y?: number;
  readonly kind?: string;
  readonly sol?: number;
  readonly photo?: unknown;
}

/** Raw channel legend entry inside `site.json` overlays (metadata only; labels translated in UI). */
export interface MarswalkMineralChannel {
  readonly label: string;
  readonly band: string;
  readonly color: string;
  readonly lo: number;
  readonly hi: number;
}

/** Typed representation of `public/sites/jezero-delta/site.json`. */
export interface MarswalkSiteData {
  readonly id: string;
  readonly name: string;
  readonly crater?: string;
  readonly datum?: string;
  readonly georef?: {
    readonly lon0: number;
    readonly lat0: number;
    readonly rMars: number;
    readonly rEq?: number;
    readonly rPol?: number;
  };
  readonly georefCheck?: {
    readonly n: number;
    readonly meanDz: number;
    readonly stdDz: number;
  };
  readonly rings: readonly TerrainRingSpec[];
  readonly overlays?: {
    readonly minerals?: {
      readonly file: string;
      readonly half: number;
      /**
       * Provenance offset (meters) already baked into `minerals.png` during build-time
       * CRISM resampling (`build_site.py`). Kept strictly for English credit attribution;
       * MUST NEVER be re-applied to runtime UVs or route/POI coordinates.
       */
      readonly shiftM?: readonly [number, number];
      readonly channels?: readonly MarswalkMineralChannel[];
    };
    readonly thermal?: {
      readonly file: string;
      readonly half: number;
    };
  };
  readonly pois: readonly SitePoiRaw[];
}

/** 3D surface overlay layer identifiers exposed by `TerrainView` and `marswalkTerrain`. */
export type OverlayLayerId = 'ortho' | 'slope' | 'minerals' | 'thermal';

/** English UI labels for `OverlayLayerId` (never Italian `site.json` strings). */
export const OVERLAY_LAYER_LABELS_EN: Readonly<Record<OverlayLayerId, string>> = {
  ortho: 'HiRISE Ortho Mosaic (NASA/JPL-Caltech/UArizona)',
  slope: 'Terrain Slope Hazard (<10°, 10–20°, 20–30°, >30°)',
  minerals: 'CRISM Mineralogy (Olivine / Fe-Mg Clays / Carbonates — ~272 m MRO registration)',
  thermal: 'THEMIS Thermal Inertia (Nighttime IR, 100 m/px — ASU/NASA)',
};

/** Structural input compatible with `RejectedPathOption` from `src/routing/searchTrace.ts`. */
export interface RouteRejectedPathInput {
  readonly id: string;
  readonly label: string;
  readonly reason: string;
  readonly path: readonly LocalPoint3[];
  readonly colorHex?: string;
}

/** Interactive handle returned by `createProceduralTerrainFromBundle` and `createJezeroTerrain`. */
export interface MarswalkTerrainHandle {
  readonly group: THREE.Group;
  /** Reference elevation datum in areoid meters matching `origin.elevation_m` (`y_scene = 0`). */
  h0: number;
  /** Maximum horizontal half-extent covered in scene meters. */
  maxHalf: number;
  /** True when rendering pure bundle procedural fallback rather than NASA clipmap rings. */
  isProceduralFallback: boolean;
  readonly origin: SceneOrigin;
  readonly verticalExaggeration: number;
  /**
   * Unified walkable scene-Y elevation (meters * verticalExaggeration relative to `h0`)
   * grounded on `bundle.elevation` inside bundle bounds (falling back to loaded outer rings
   * strictly outside bundle bounds, or `NaN` on unmapped / `NO_ELEVATION` cells).
   */
  heightAtSceneXZ(x: number, z: number): number;
  /**
   * True physical terrain slope in degrees (always un-exaggerated, derived from `bundle.slope`
   * inside bundle bounds or outer slope rasters strictly outside, or `NaN` if unavailable).
   */
  slopeDegAtSceneXZ(x: number, z: number): number;
  setLayer(layer: OverlayLayerId): void;
  setVerticalExaggeration(exaggeration: number): void;
  updateLod(cameraX: number, cameraZ: number): void;
  dispose(): void;
}

/** Interactive handle returned by `makeMarsSky`. */
export interface MarswalkSkyHandle {
  readonly skyMesh: THREE.Mesh;
  updatePosition(cameraOrPos: THREE.Camera | THREE.Vector3): void;
  dispose(): void;
}

/** Interactive handle returned by `createMarswalkPois`. */
export interface MarswalkPoisHandle {
  readonly group: THREE.Group;
  setEndpoints(
    start: LocalPoint | null,
    destination: LocalPoint | null,
    destinationLabel?: string,
  ): void;
  setPois(pois: readonly UnifiedPoi[]): void;
  setVisited(visitedIds: ReadonlySet<string>): void;
  setVerticalExaggeration(exaggeration: number): void;
  findNearestPoi(
    sceneX: number,
    sceneZ: number,
    maxDistance_m?: number,
  ): { poi: UnifiedPoi; distance_m: number } | null;
  update(elapsedS: number, cameraPos?: THREE.Vector3): void;
  dispose(): void;
}
